5	namespace Tests\Feature\SuperAdmin;
6	
7	use App\Models\Role;
8	use App\Models\User;
9	use App\Modules\Events\Models\Event;
10	use App\Modules\Events\Models\Registration;
11	use Illuminate\Support\Facades\Route;
12	use Illuminate\Testing\TestResponse;
13	use PHPUnit\Framework\Attributes\Test;
14	use PHPUnit\Framework\Attributes\TestDox;
15	use Symfony\Component\HttpFoundation\BinaryFileResponse;
16	use Symfony\Component\HttpFoundation\StreamedResponse;
17	use Tests\Feature\FeatureTestCase;
18	use Tests\Feature\SuperAdmin\Support\InteractsWithSuperAdmin;
19	
20	/**
21	 * Capsule T4 — platform-admin export of a single event's registration list.
22	 *
23	 * The rows carry attendee personal data, so the endpoint must be gated by the
24	 * same global capability that already governs platform-wide event visibility
25	 * (events.view.global) rather than by generic admin-area membership.
26	 */
27	class AdminEventRegistrationExportTest extends FeatureTestCase
28	{
29	    use InteractsWithSuperAdmin;
30	
31	    private const EXPORT_ROUTE = 'admin.events.registrations.export';
32	
33	    // -------------------------------------------------------------------------
34	    // AC1 / AC4 / AC5 — CSV download scoped to the requested event
35	    // -------------------------------------------------------------------------
36	
37	    #[Test]
38	    #[TestDox('T4-EXPORT-01 [P0] Given a platform admin when they export an event then only that event\'s registrations are streamed as a CSV download')]
39	    public function platform_admin_exports_only_the_requested_events_registrations(): void
40	    {
41	        $workspace = $this->createWorkspace();
42	        $otherWorkspace = $this->createWorkspace();
43	
44	        $event = Event::factory()->for($workspace)->create(['title' => 'Delivery Complaint Event']);
45	        $otherEvent = Event::factory()->for($otherWorkspace)->create(['title' => 'Unrelated Event']);
46	
47	        $this->registerAttendee($event, 'first.attendee@example.test');
48	        $this->registerAttendee($event, 'second.attendee@example.test');
49	        $this->registerAttendee($otherEvent, 'other.event.attendee@example.test');
50	
51	        $admin = $this->createPlatformSuperAdmin($workspace);
52	
53	        $response = $this->actingAs($admin)->get($this->exportUrl($event));
54	
55	        $response->assertOk();
56	
57	        // AC5 — delivered as a CSV download naming the event it belongs to.
58	        $this->assertStringContainsString('text/csv', (string) $response->headers->get('Content-Type'));
59	        $disposition = (string) $response->headers->get('Content-Disposition');
60	        $this->assertStringContainsString('attachment', $disposition);
61	        $this->assertStringContainsString($event->uuid, $disposition);
62	
63	        // AC4 — the requested event's registrations, and nothing from another event.
64	        $body = $this->bodyOf($response);
65	        $this->assertStringContainsString('first.attendee@example.test', $body);
66	        $this->assertStringContainsString('second.attendee@example.test', $body);
67	        $this->assertStringNotContainsString('other.event.attendee@example.test', $body);
68	    }
69	
70	    // -------------------------------------------------------------------------
71	    // AC3 — admin-area access alone does not unlock attendee personal data
72	    // -------------------------------------------------------------------------
73	
74	    #[Test]
75	    #[TestDox('T4-EXPORT-02 [P0] Given an admin-area user without global event visibility when they request the export then they are refused and receive no registration data')]
76	    public function admin_area_user_without_global_event_visibility_is_refused(): void
77	    {
78	        $workspace = $this->createWorkspace();
79	        $event = Event::factory()->for($workspace)->create(['title' => 'Delivery Complaint Event']);
80	        $this->registerAttendee($event, 'protected.attendee@example.test');
81	
82	        // Reaches the admin area (system-admin flagged role) but was never
83	        // granted the global event-visibility capability.
84	        $role = Role::query()->create([
85	            'name' => 'Support Desk Without Event Visibility',
86	            'key' => 't4-support-desk-no-event-visibility',
87	            'description' => 'Test-only system role that reaches the admin area but cannot view events platform-wide.',
88	            'is_system_role' => false,
89	            'is_system_admin' => true,
90	        ]);
91	
92	        $supportUser = User::factory()->create([
93	            'email_verified_at' => now(),
94	            'current_team_id' => $workspace->id,
95	        ]);
96	        $workspace->users()->attach($supportUser, ['role' => $role->key]);
97	        $supportUser = $supportUser->fresh(['currentTeam']);
98	
99	        // Precondition: this actor genuinely reaches the platform-admin area.
100	        $this->actingAs($supportUser)->get(route('admin.dashboard'))->assertOk();
101	
102	        $response = $this->actingAs($supportUser)->get($this->exportUrl($event));
103	
104	        $response->assertForbidden();
105	        $this->assertStringNotContainsString('protected.attendee@example.test', $this->bodyOf($response));
106	    }
107	
108	    // -------------------------------------------------------------------------
109	    // AC2 / AC6 — config gating agrees with the endpoint, neighbours untouched
110	    // -------------------------------------------------------------------------
111	
112	    #[Test]
113	    #[TestDox('T4-EXPORT-03 [P0] Given the route-permission config when the export route is added then it requires global event visibility and pre-existing admin event entries are unchanged')]
114	    public function export_route_is_capability_gated_without_widening_existing_admin_routes(): void
115	    {
116	        /** @var array<string, string|null> $permissions */
117	        $permissions = config('route_permissions.routes');
118	
119	        $this->assertSame(
120	            'events.view.global',
121	            $permissions[self::EXPORT_ROUTE] ?? null,
122	            'The export route must be gated by the global event-visibility capability it enforces.',
123	        );
124	
125	        // AC6 — the neighbouring admin event entries keep their original gates.
126	        $this->assertSame('events.view.global', $permissions['admin.events.index'] ?? null);
127	        $this->assertSame('events.view.global', $permissions['admin.events.show'] ?? null);
128	        $this->assertSame('events.update.global', $permissions['admin.events.edit'] ?? null);
129	        $this->assertSame('system_admin_access', $permissions['admin.dashboard'] ?? null);
130	    }
131	
132	    // -------------------------------------------------------------------------
133	    // Helpers
134	    // -------------------------------------------------------------------------
135	
136	    private function exportUrl(Event $event): string
137	    {
138	        $this->assertTrue(
139	            Route::has(self::EXPORT_ROUTE),
140	            'Named route ['.self::EXPORT_ROUTE.'] does not exist.',
141	        );
142	
143	        return route(self::EXPORT_ROUTE, $event->uuid);
144	    }
145	
146	    private function registerAttendee(Event $event, string $email): Registration
147	    {
148	        return Registration::unguarded(fn (): Registration => Registration::query()->create([
149	            'team_id' => $event->team_id,
150	            'event_id' => $event->id,
151	            'email' => $email,
152	            'email_hash' => hash('sha256', $email),
153	            'source' => 'direct',
154	            'full_name' => 'Attendee '.substr(md5($email), 0, 6),
155	            'consent_accepted_at' => now(),
156	        ]));
157	    }
158	
159	    private function bodyOf(TestResponse $response): string
160	    {
161	        $base = $response->baseResponse;
162	
163	        if ($base instanceof StreamedResponse || $base instanceof BinaryFileResponse) {
164	            return $response->streamedContent();
165	        }
166	
167	        return (string) $base->getContent();
168	    }
169	}
