12	
13	trait InteractsWithSuperAdmin
14	{
15	    /**
16	     * Ensure roles + permissions are seeded before each test.
17	     *
18	     * Tests using this trait may extend TestCase directly (not FeatureTestCase)
19	     * and therefore do not call seedPermissionsOnce() in their own setUp.
20	     * The count guard prevents double-seeding when a test also inherits from
21	     * FeatureTestCase (which already calls the same seeder).
22	     *
23	     * Added by Story 1-11C for UserAdministrationTest.
24	     */
25	    protected function setUp(): void
26	    {
27	        parent::setUp();
28	
29	        if (RolePermission::count() === 0) {
30	            $this->seed(\Database\Seeders\Testing\TestPermissionSeeder::class);
31	        }
32	    }
33	
34	    /**
35	     * Create the platform's is_system_team team for tests that exercise the
36	     * grantSystemAdmin / revokeSystemAdmin service paths.
37	     *
38	     * The production system team is seeded by SuperadminSeeder; in tests with
39	     * RefreshDatabase it must be created explicitly before calling the grant
40	     * service method.
41	     */
42	    protected function createSystemTeam(): Team
43	    {
44	        $owner = User::factory()->create(['email_verified_at' => now()]);
45	
46	        /** @var Team $team */
47	        $team = Team::factory()->create([
48	            'user_id'         => $owner->id,
49	            'is_system_team'  => true,
50	            'personal_team'   => false,
51	        ]);
52	
53	        return $team;
54	    }
55	
56	    /**
57	     * @param  array<string, mixed>  $teamAttributes
58	     */
59	    protected function createWorkspace(array $teamAttributes = []): Team
60	    {
61	        $owner = User::factory()->create(['email_verified_at' => now()]);
62	        /** @var Team $team */
63	        $team = Team::factory()
64	            ->nonPersonal()
65	            ->create(array_merge(['user_id' => $owner->id], $teamAttributes));
66	
67	        $team->users()->attach($owner, ['role' => UserRole::ownerDefault()->value]);
68	        $owner->forceFill(['current_team_id' => $team->id])->save();
69	
70	        /** @var Team $freshTeam */
71	        $freshTeam = $team->fresh(['owner', 'users']);
72	
73	        return $freshTeam;
74	    }
75	
76	    protected function createPlatformSuperAdmin(?Team $team = null): User
77	    {
78	        $workspace = $team ?? $this->createWorkspace();
79	        /** @var User $user */
80	        $user = User::factory()->create([
81	            'email_verified_at' => now(),
82	            'current_team_id' => $workspace->id,
83	        ]);
84	
85	        $workspace->users()->attach($user, ['role' => UserRole::SYSTEM_ADMIN->value]);
86	
87	        /** @var User $freshUser */
88	        $freshUser = $user->fresh(['currentTeam']);
89	
90	        return $freshUser;
91	    }
92	
93	    /**
94	     * @param  array<string, mixed>  $attributes
95	     */
96	    protected function createWorkspaceMember(Team $team, UserRole $role, array $attributes = []): User
97	    {
98	        /** @var User $user */
99	        $user = User::factory()->create(array_merge([
100	            'email_verified_at' => now(),
101	            'current_team_id' => $team->id,
102	        ], $attributes));
103	
104	        $team->users()->attach($user, ['role' => $role->value]);
105	
106	        /** @var User $freshUser */
107	        $freshUser = $user->fresh(['currentTeam']);
108	
109	        return $freshUser;
110	    }
111	
112	    protected function suspendWorkspace(Team $team): Team
113	    {
114	        $team->forceFill(['status' => TeamStatus::SUSPENDED])->save();
115	
116	        /** @var Team $freshTeam */
117	        $freshTeam = $team->fresh();
118	
119	        return $freshTeam;
120	    }
121	}
