    public function super_admin_events_catalog_is_complete_and_identical_in_english_and_turkish(): void
    {
        $expectedKeys = [
            'actions.view',
            'columns.actions',
            'columns.date',
            'columns.event',
            'columns.registrations',
            'columns.state',
            'columns.workspace',
            'empty',
            'filter_all_states',
            'search_placeholder',
            'subtitle',
            'workspace_placeholder',
        ];
        sort($expectedKeys);

        foreach (['en', 'tr'] as $locale) {
            $catalog = require base_path("lang/vendor/super-admin/{$locale}/super-admin.php");
            $events = $catalog['events'] ?? null;

            $this->assertIsArray($events, "The {$locale} SuperAdmin catalog must define an events array.");

            $flat = $this->flatten($events);
            $actualKeys = array_keys($flat);
            sort($actualKeys);

            $this->assertSame(
                $expectedKeys,
                $actualKeys,
                "The {$locale} SuperAdmin Events catalog must contain the complete canonical key set.",
            );

            foreach ($flat as $key => $value) {
                $this->assertNotSame(
                    '',
                    trim($value),
                    "The {$locale} SuperAdmin Events translation [{$key}] must not be empty.",
                );
            }
        }
    }

    /**
     * @param  array<string, mixed>  $value
     * @return array<string, string>
     */
    private function flatten(array $value, string $prefix = ''): array
    {
        $flat = [];
        foreach ($value as $key => $sub) {
            $path = $prefix === '' ? (string) $key : $prefix.'.'.$key;
            if (is_array($sub)) {
